/** An OKLCH colour as numbers (L 0..1, C unbounded ~0..0.4, H degrees). */
export interface Oklch {
  L: number
  C: number
  H: number
}

/** parseOklch() result: numbers plus the raw C/H substrings for round-tripping. */
export interface ParsedOklch extends Oklch {
  rawC: string
  rawH: string
}

/** One mode block (or resolved surface): flat token → value strings. */
export type ModeVars = Record<string, string>

/** A schema-valid preset entry (post-validation shape). */
export interface PresetDef {
  character?: string
  light: ModeVars
  dark: ModeVars
}

/** An UNVALIDATED preset entry, as parsed from JSON or user input. */
export interface RawPresetEntry {
  character?: unknown
  light?: ModeVars
  dark?: ModeVars
}

export interface ClampReport {
  log: string[]
  skips: string[]
  residuals: string[]
}

export interface FontFile {
  path: string
  weight: string
  style: string
}

export interface FontEntry {
  family: string
  category: string
  files: FontFile[]
  license?: string
  source?: string
}

/** src/themes/fonts.json minus its $comment: slug → family entry. */
export type FontsManifest = Record<string, FontEntry>

export interface FontStack {
  stack: string
  files: string[]
  passthrough?: boolean
  entry?: FontEntry
}

/** A point in OKLab cartesian space (for ΔE). */
export interface OklabPoint {
  L: number
  a: number
  b: number
}

